/**
 * The one-command bootstrap of a nested hz, from the parent's project page
 * (operator, 2026-10-01: *"spin it up with a command that is generated by the
 * red line project in the office"*).
 *
 * [Add nested instance] asks three things — the machine's name, the rung's
 * name, the rung it is promoted into from — and hz declares both, then shows
 * ONE command, once, with its expiry. Running it as root on a fresh Ubuntu box
 * provisions the nested hz and connects it here. Nothing else is asked: what
 * the command does is on the command's own output, and in the README.
 *
 * The state a nested instance shows is hz's own records, never a dial
 * (CLAUDE.md #1): declared · command generated (expires …) · enrolled ·
 * connected (last pull …) · never connected.
 *
 * Amendment 6 (flows over prose): a table, a one-line empty state with the Add
 * button beside it. `BootstrapCommandPanel` is apart from its dialog so the
 * render check can draw it (a Dialog renders through a portal).
 */
import { useState } from "react";
import { Link } from "@tanstack/react-router";
import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  MenuItem,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Tooltip,
  Typography,
} from "@mui/material";
import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import type {
  EnvironmentResp,
  InstanceNestedResp,
  InstanceResp,
  NestedBootstrapResp,
} from "../../api/generated-types";
import { useNestedBootstrap } from "../../api/instanceHooks";
import { AddButton, EmptyRow, TabHeader } from "../model/FlowBits";
import { ToneChip } from "../model/ModelBits";

function stamp(unix: number): string {
  return new Date(unix * 1000).toISOString().replace("T", " ").replace(/\.\d+Z$/, "Z");
}

export interface NestedStateReading {
  state: string;
  label: string;
  tone: "fresh" | "late" | "fault" | "neutral";
}

/** The one state line, from the row's `nested` facts. A row with no facts
 * (an older hz) reads as declared — the record is all there is. */
export function readNestedState(n: InstanceNestedResp | undefined): NestedStateReading {
  switch (n?.state) {
    case "command-generated":
      return {
        state: "command-generated",
        label: n.grantExpiresAt ? `command generated (expires ${stamp(n.grantExpiresAt)})` : "command generated",
        tone: "late",
      };
    case "enrolled":
      return { state: "enrolled", label: "enrolled — waiting for its first pull", tone: "late" };
    case "connected":
      return {
        state: "connected",
        label: `connected (last pull ${stamp(n.lastPullAt)}${n.lastPullRung ? ` · ${n.lastPullRung}` : ""})`,
        tone: "fresh",
      };
    case "never-connected":
      return { state: "never-connected", label: "never connected", tone: "fault" };
    default:
      return { state: "declared", label: "declared", tone: "neutral" };
  }
}

export function NestedStateChip({ nested }: { nested: InstanceNestedResp | undefined }) {
  const r = readNestedState(nested);
  return (
    <span data-nested-state={r.state}>
      <ToneChip label={r.label} tone={r.tone} />
    </span>
  );
}

/** The command, shown once, with its expiry — or the refusal, verbatim. */
export function BootstrapCommandPanel({ resp }: { resp: NestedBootstrapResp }) {
  const [copied, setCopied] = useState(false);
  return (
    <Box data-bootstrap-result>
      {resp.warning ? (
        <Alert severity="warning" sx={{ mb: 2 }} data-bootstrap-warning>
          {resp.warning}
        </Alert>
      ) : null}
      <Typography variant="body2" sx={{ mb: 1 }}>
        Run this as root on the fresh box for <code>{resp.machine}</code> ({resp.rung}). Single use; expires{" "}
        <span data-bootstrap-expires>{stamp(resp.expiresAt)}</span>.
      </Typography>
      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
        <TextField
          fullWidth
          size="small"
          value={resp.command}
          slotProps={{ input: { readOnly: true }, htmlInput: { "data-bootstrap-command": true } }}
          sx={{ "& input": { fontFamily: "monospace", fontSize: 13 } }}
        />
        <Tooltip title={copied ? "Copied" : "Copy"}>
          <IconButton
            aria-label="Copy the command"
            onClick={() => {
              void navigator.clipboard?.writeText(resp.command);
              setCopied(true);
              setTimeout(() => setCopied(false), 1500);
            }}
          >
            <ContentCopyIcon fontSize="small" />
          </IconButton>
        </Tooltip>
      </Box>
      <Typography variant="caption" sx={{ display: "block", mt: 1, color: "text.secondary" }} data-bootstrap-shown-once>
        Shown once. {resp.revoked ? "The earlier unused command for this machine no longer works. " : ""}
        {resp.reused.length > 0 ? `Reused the existing ${resp.reused.join(" and ")}. ` : ""}
        The box needs outbound HTTPS to this hz&apos;s public address and outbound UDP to its WireGuard endpoint —
        nothing inbound.
      </Typography>
    </Box>
  );
}

export function AddNestedInstanceDialog({
  project,
  rungs,
  open,
  onClose,
}: {
  project: string;
  /** This project's own rungs — the from-rung choices. */
  rungs: EnvironmentResp[];
  open: boolean;
  onClose: () => void;
}) {
  const gen = useNestedBootstrap();
  const [machine, setMachine] = useState("");
  const [rung, setRung] = useState("");
  const [from, setFrom] = useState("");
  const close = () => {
    gen.reset();
    setMachine("");
    setRung("");
    setFrom("");
    onClose();
  };
  const ready = machine.trim() !== "" && rung.trim() !== "" && from !== "";
  return (
    <Dialog open={open} onClose={close} fullWidth maxWidth="md">
      <DialogTitle>Add nested instance to {project}</DialogTitle>
      <DialogContent>
        {gen.data ? (
          <BootstrapCommandPanel resp={gen.data} />
        ) : (
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, pt: 1 }}>
            <TextField
              label="Machine name"
              value={machine}
              onChange={(e) => setMachine(e.target.value)}
              helperText="The box the nested hz runs on, e.g. loadtest-hz"
              autoFocus
            />
            <TextField
              label="Rung name"
              value={rung}
              onChange={(e) => setRung(e.target.value)}
              helperText={`Declared as ${project}/${rung.trim() || "<rung>"}, posture prod, placed in that machine`}
            />
            <TextField
              select
              label="Promoted from"
              value={from}
              onChange={(e) => setFrom(e.target.value)}
              helperText={rungs.length === 0 ? `${project} has no rung to promote from — add one first.` : " "}
            >
              {rungs.map((r) => (
                <MenuItem key={r.name} value={r.name}>
                  {r.name} ({r.posture})
                </MenuItem>
              ))}
            </TextField>
            {gen.error ? <Alert severity="error">{gen.error.message}</Alert> : null}
          </Box>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={close}>{gen.data ? "Done" : "Cancel"}</Button>
        {gen.data ? null : (
          <Button
            variant="contained"
            disabled={!ready || gen.isPending}
            onClick={() => gen.mutate({ project, machine: machine.trim(), rung: rung.trim(), from })}
          >
            {gen.isPending ? "Generating…" : "Generate command"}
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
}

/**
 * The project page's nested instances: every nested row this project owns,
 * the rungs placed in it, and its state.
 */
export function NestedInstancesSection({
  project,
  instances,
  environments,
  onAdd,
}: {
  project: string;
  instances: { rows?: InstanceResp[]; error?: string; loading: boolean };
  environments: EnvironmentResp[];
  onAdd: () => void;
}) {
  const add = <AddButton label="Add nested instance" ariaLabel={`Add a nested instance to ${project}`} onClick={onAdd} />;
  const mine = (instances.rows ?? []).filter((r) => r.role === "nested" && r.project === project);
  return (
    <Box data-nested-instances>
      <TabHeader title="Nested instances" action={add} />
      {instances.error ? (
        <Alert severity="error" sx={{ mb: 3 }}>
          hz could not be asked which nested instances it knows: {instances.error}
        </Alert>
      ) : instances.loading ? (
        <Typography sx={{ color: "text.secondary", mb: 3 }}>Asking hz which nested instances it knows…</Typography>
      ) : mine.length === 0 ? (
        <Box sx={{ mb: 3 }}>
          <EmptyRow text={`No nested instances in ${project}.`} action={add} />
        </Box>
      ) : (
        <TableContainer component={Paper} sx={{ mb: 3 }}>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Instance</TableCell>
                <TableCell>Rungs</TableCell>
                <TableCell>State</TableCell>
                <TableCell>Address</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {mine.map((r) => (
                <TableRow key={r.name} hover data-nested-row={r.name}>
                  <TableCell>
                    <Link to="/instances/$instance" params={{ instance: r.name }} style={{ fontFamily: "monospace", fontWeight: 600 }}>
                      {r.name}
                    </Link>
                  </TableCell>
                  <TableCell sx={{ fontFamily: "monospace" }}>
                    {environments
                      .filter((e) => e.upstream === r.name)
                      .map((e) => `${e.project}/${e.name}`)
                      .join(" · ") || "—"}
                  </TableCell>
                  <TableCell>
                    <NestedStateChip nested={r.nested} />
                  </TableCell>
                  <TableCell sx={{ fontFamily: "monospace", color: "text.secondary" }}>{r.address}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Box>
  );
}
